32	        // itself; skip exporting the shim path so the shim-backed tests
33	        // print a skip notice. A compiler that ran but rejected the source
34	        // is a real error and must fail loudly (the Ok arm above).
35	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
