218	 * Shared fstat handling for tracked fds: perform the real fstat (via the
219	 * passed function), apply fault/lie policy, log the result, and tell the
220	 * caller what to return.
221	 */
222	static int handle_fstat(int fd, void *st, int is64)
223	{
224	    int rc = is64 ? real_fstat64(fd, (struct stat64 *)st)
225	                  : real_fstat(fd, (struct stat *)st);
226	
227	    if (!is_tracked(fd))
228	        return rc;
229	
230	    if (rc != 0) {
231	        trace("FSTAT ret=-1 mode=00000 size=0\n");
232	        return rc;
233	    }
234	
235	    mode_t real_mode;
236	    off_t real_size;
237	    if (is64) {
238	        struct stat64 *s = (struct stat64 *)st;
239	        real_mode = s->st_mode;
240	        real_size = s->st_size;
241	    } else {
242	        struct stat *s = (struct stat *)st;
243	        real_mode = s->st_mode;
244	        real_size = s->st_size;
245	    }
246	
247	    if (cfg_fail_fstat) {
248	        trace("FSTAT ret=-1 mode=0%04o size=%lld\n",
249	              (unsigned)(real_mode & 07777), (long long)real_size);
250	        errno = EBADF;
251	        return -1;
252	    }
253	
254	    mode_t reported = real_mode;
255	    if (cfg_lie_mode >= 0) {
256	        reported = (real_mode & ~(mode_t)07777) | (mode_t)cfg_lie_mode;
257	        if (is64)
258	            ((struct stat64 *)st)->st_mode = reported;
259	        else
260	            ((struct stat *)st)->st_mode = reported;
261	    }
262	
263	    trace("FSTAT ret=0 mode=0%04o size=%lld\n",
264	          (unsigned)(reported & 07777), (long long)real_size);
265	    return 0;
266	}
267	
268	/* ----- intercepted libc functions ----- */
269	
270	int open(const char *path, int flags, ...)
271	{
272	    if (!real_open)
273	        real_open = (open_fn)dlsym(RTLD_NEXT, "open");
274	
