    n += fmt_u64(line + n, (unsigned long long)req);
    for (p = " ret="; *p; p++)
        line[n++] = *p;
    if (ret < 0) {
        for (p = "-1 errno=EIO"; *p; p++)
            line[n++] = *p;
    } else {
        n += fmt_u64(line + n, (unsigned long long)ret);
    }
    line[n++] = '\n';
    trace_write(line, n);
