//!   failure succeeds.
//!
//! The faults are injected by the LD_PRELOAD shim tests/support/randtrap,
//! which traps the guest's getrandom(2) syscall with seccomp and emulates
//! it in a SIGSYS handler (the getrandom crate issues the syscall with
//! inline assembly, so symbol interposition cannot see it). Bytes the shim
//! hands out follow a fixed pattern (0x80, 0x81, ... by draw index) so the
//! tests can recognise them in files and output.
#![cfg(unix)]

use std::fs;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

const KEY_LEN: usize = 32;
const MODE_0600: u32 = 0o600;
const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];

fn bin() -> PathBuf {
    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
}

fn randtrap_so() -> Option<PathBuf> {
    option_env!("WRAPFILE_RANDTRAP_SO").map(PathBuf::from)
}

/// The byte the randtrap shim hands to the guest at global draw index `i`
/// (see pattern_byte() in randtrap.c).
fn pattern_byte(i: usize) -> u8 {
    (0x80 + (i % 64)) as u8
}

/// The first `n` bytes the shim would deliver.
fn pattern(n: usize) -> Vec<u8> {
    (0..n).map(pattern_byte).collect()
}

// ---------------------------------------------------------------------------
// scratch directory
// ---------------------------------------------------------------------------

struct Tmp {
    path: PathBuf,
}

impl Tmp {
    fn new(label: &str) -> Tmp {
        static SEQ: AtomicU64 = AtomicU64::new(0);
        let path = std::env::temp_dir().join(format!(
            "wrapfile-keygen-random-tests-{}-{}-{}",
            std::process::id(),
            label,
            SEQ.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir_all(&path).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
        Tmp { path }
    }

    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
        self.path.join(name)
    }
}

impl Drop for Tmp {
    fn drop(&mut self) {
        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
        let _ = fs::remove_dir_all(&self.path);
    }
}

// ---------------------------------------------------------------------------
// running the binary
// ---------------------------------------------------------------------------

struct Run {
    rc: i32,
    out: Vec<u8>,
    err: Vec<u8>,
}

/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
/// wrapper, with the randtrap shim preloaded and a trace file configured.
fn run_keygen(key: &Path, umask: u32, so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
    let mut cmd = Command::new("/bin/sh");
    cmd.arg("-c")
        .arg(format!("umask {umask:04o}; exec \"$@\""))
        .arg("sh")
        .arg(bin())
        .arg("keygen")
        .arg(key)
        .env("LD_PRELOAD", so)
        .env("WRAPFILE_TEST_TRACE_FILE", trace);
    for (k, v) in extra_env {
        cmd.env(k, v);
    }
    let o = cmd.output().unwrap();
    Run {
        rc: o.status.code().unwrap_or(-1),
        out: o.stdout,
        err: o.stderr,
    }
}

/// Run `wrapfile <args...>` directly, with the randtrap shim preloaded.
fn run_bin(args: &[&str], so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
    let mut cmd = Command::new(bin());
    cmd.args(args)
        .env("LD_PRELOAD", so)
        .env("WRAPFILE_TEST_TRACE_FILE", trace);
    for (k, v) in extra_env {
        cmd.env(k, v);
    }
    let o = cmd.output().unwrap();
    Run {
        rc: o.status.code().unwrap_or(-1),
        out: o.stdout,
        err: o.stderr,
    }
}

// ---------------------------------------------------------------------------
// shim trace log
// ---------------------------------------------------------------------------

/// Create the trace file up front (mode 0644) so that it stays readable
/// even when the child runs under umask 0777 -- the shim opens it O_APPEND.
fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
    let p = dir.join(name);
    fs::File::create(&p).unwrap();
    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
    p
}

/// False when the shim could not arm the seccomp trap on this system (or
/// was not loaded at all); the caller then skips instead of failing.
fn trap_armed(trace: &Path) -> bool {
    let text = fs::read_to_string(trace).unwrap();
    if text.lines().any(|l| l == "TRAP armed") {
        return true;
    }
    eprintln!("skipping: randtrap shim could not arm the seccomp trap here");
    false
}

#[derive(Debug)]
struct GrEvent {
    req: usize,
    ret: i64, // negative: the call failed with the injected errno
}

impl GrEvent {
    fn failed(&self) -> bool {
        self.ret < 0
    }

    fn delivered(&self) -> usize {
        if self.ret > 0 { self.ret as usize } else { 0 }
    }
}

/// The GETRANDOM lines of the trace, in call order.
fn getrandom_events(trace: &Path) -> Vec<GrEvent> {
    let text = fs::read_to_string(trace).unwrap();
    text.lines()
        .filter_map(|line| {
            let mut parts = line.split_whitespace();
            if parts.next() != Some("GETRANDOM") {
                return None;
            }
            let mut req = None;
            let mut ret = None;
            for kv in parts {
                let (k, v) = kv.split_once('=')?;
                match k {
                    "req" => req = v.parse().ok(),
                    "ret" => ret = v.parse().ok(),
                    _ => {}
                }
            }
            Some(GrEvent { req: req?, ret: ret? })
        })
        .collect()
}

// ---------------------------------------------------------------------------
// filesystem assertions
// ---------------------------------------------------------------------------

fn mode_of(path: &Path) -> u32 {
    fs::symlink_metadata(path).unwrap().mode() & 0o7777
}

fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
}

/// The failure contract for an unusable random source: exit 1, an
/// explanation naming the random source on stderr, nothing on stdout, and
/// no trace of this invocation left in the parent directory -- in
/// particular no file at the target path that could be mistaken for a key
/// (empty, partial, zero-padded, or a full-length stand-in).
fn assert_failed_random(key: &Path, run: &Run, dir: &Path, allowed_entries: &[&str]) {
    assert_eq!(run.rc, 1, "an unfinishable random draw must exit 1");
    assert!(
        run.out.is_empty(),
        "stdout must stay empty on random-source failure, got {}",
        String::from_utf8_lossy(&run.out)
    );
    let stderr = String::from_utf8_lossy(&run.err);
    assert!(
        stderr.contains("cryptographic random source unavailable"),
        "stderr must state that the cryptographic random source is \
         unavailable (without pinning the OS-specific error text), got: {stderr}"
    );

    assert!(
        !key.exists(),
        "no file may be left at the target path after a random-source failure"
    );
    assert_no_leftovers(dir, allowed_entries);
}

fn assert_no_leftovers(dir: &Path, allowed_entries: &[&str]) {
    let mut leftovers: Vec<String> = fs::read_dir(dir)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .filter(|n| !allowed_entries.contains(&n.as_str()))
        .collect();
    leftovers.sort();
    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
}

// A pre-existing object that must survive a failed keygen byte-for-byte.
struct Sentinel {
    path: PathBuf,
    bytes: Vec<u8>,
    mode: u32,
    inode: u64,
}

impl Sentinel {
    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
        let path = dir.join(name);
        fs::write(&path, bytes).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
        let meta = fs::metadata(&path).unwrap();
        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
    }

    fn assert_untouched(&self) {
        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
    }
}

// ---------------------------------------------------------------------------
// tests
// ---------------------------------------------------------------------------

#[test]
fn random_source_unavailable_before_any_byte_saves_nothing() {
    let Some(so) = randtrap_so() else {
        eprintln!("skipping: randtrap shim not available on this target");
        return;
    };

    let tmp = Tmp::new("rand-fail-empty");
    let key = tmp.child("key");
    let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
    let parent_mode_before = mode_of(&tmp.path);
    let trace = prepare_trace(&tmp.path, "trace.log");

    // The random source reports it cannot deliver anything at all.
    let run = run_keygen(
        &key,
        0o022,
        &so,
        &[("WRAPFILE_TEST_GETRANDOM_FAIL", "1")],
        &trace,
    );
    if !trap_armed(&trace) {
        return;
    }

    // The injected failure really was hit, before any byte was drawn.
    let events = getrandom_events(&trace);
    assert!(!events.is_empty(), "the random draw must have been attempted");
    assert!(
        events.iter().all(GrEvent::failed),
        "no random byte may have been delivered in this scenario: {events:?}"
    );

    assert_failed_random(&key, &run, &tmp.path, &["sibling", "trace.log"]);
    sibling.assert_untouched();
    assert_eq!(
        mode_of(&tmp.path),
        parent_mode_before,
        "parent directory permissions must be untouched"
    );

    // The failure was transient: a retry without the fault saves a full key.
    let trace2 = prepare_trace(&tmp.path, "trace2.log");
    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
    assert_eq!(run2.rc, 0, "stderr={}", String::from_utf8_lossy(&run2.err));
    let bytes = fs::read(&key).unwrap();
    assert_eq!(bytes.len(), KEY_LEN, "the retry must save a full 32-byte key");
    assert_eq!(mode_of(&key), MODE_0600);
    sibling.assert_untouched();
}

#[test]
fn random_source_failure_after_partial_bytes_saves_nothing() {
    let Some(so) = randtrap_so() else {
        eprintln!("skipping: randtrap shim not available on this target");
        return;
    };

    let tmp = Tmp::new("rand-fail-partial");
    let key = tmp.child("key");
    let sibling = Sentinel::file(&tmp.path, "sibling", b"keep-me", 0o600);
    let parent_mode_before = mode_of(&tmp.path);
    let trace = prepare_trace(&tmp.path, "trace.log");

    // Ten bytes come out of the random source, then it fails for good
    // before the 32-byte key is complete.
    let run = run_keygen(
        &key,
        0o022,
        &so,
        &[("WRAPFILE_TEST_GETRANDOM_FAIL_AFTER", "10")],
        &trace,
    );
    if !trap_armed(&trace) {
        return;
    }

    // The scenario really happened: a short read delivered 10 of the 32
    // bytes, and the next draw failed unrecoverably.
    let events = getrandom_events(&trace);
    let delivered: usize = events.iter().map(GrEvent::delivered).sum();
    assert_eq!(delivered, 10, "exactly 10 bytes should have been drawn: {events:?}");
    assert!(
        events.iter().any(GrEvent::failed),
        "the unrecoverable random-source error must have been injected"
    );

    assert_failed_random(&key, &run, &tmp.path, &["sibling", "trace.log"]);
    sibling.assert_untouched();
    assert_eq!(
        mode_of(&tmp.path),
        parent_mode_before,
        "parent directory permissions must be untouched"
    );

    // The bytes already drawn are secret key material in waiting: they must
    // not leak to stdout/stderr, neither as raw bytes nor as text-encoded
    // (hex) diagnostics, and they must not be padded with zeroes into a
    // saved file -- there is no file at all.
    let drawn = pattern(10);
    assert!(
        !contains_slice(&run.out, &drawn) && !contains_slice(&run.err, &drawn),
        "partially drawn random bytes must never appear on stdout/stderr"
    );
    let hex: String = drawn.iter().map(|b| format!("{b:02x}")).collect();
    assert!(
        !String::from_utf8_lossy(&run.out).contains(&hex)
            && !String::from_utf8_lossy(&run.err).contains(&hex),
        "partially drawn random bytes must not appear hex-encoded either"
    );
}

#[test]
fn short_reads_from_random_source_still_complete_the_key() {
    let Some(so) = randtrap_so() else {
        eprintln!("skipping: randtrap shim not available on this target");
        return;
    };

    for umask in UMASKS {
        let tmp = Tmp::new("rand-short-reads");
        let key = tmp.child("key");
        let trace = prepare_trace(&tmp.path, "trace.log");

        // A source that only ever returns 7 bytes per call but always
        // succeeds: not a failure, the command must keep drawing.
        let run = run_keygen(
            &key,
            umask,
            &so,
            &[("WRAPFILE_TEST_GETRANDOM_PARTIAL", "7")],
            &trace,
        );
        if !trap_armed(&trace) {
            return;
        }

        assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
        assert!(
            run.err.is_empty(),
            "stderr must be empty on success, got {}",
            String::from_utf8_lossy(&run.err)
        );
        assert_eq!(
            run.out,
            format!("Key saved to {}\n", key.display()).into_bytes(),
            "stdout must be exactly the save-location message"
        );

        // Every byte in the file came from the random source, in order --
        // nothing re-fetched, invented, or zero-padded.
        let bytes = fs::read(&key).unwrap();
        assert_eq!(bytes.len(), KEY_LEN, "key must be exactly 32 bytes");
        assert_eq!(
            bytes,
            pattern(KEY_LEN),
            "the file must hold exactly the bytes the source delivered"
        );
        assert_eq!(
            mode_of(&key),
            MODE_0600,
            "key file mode must be exactly 0600 (umask {umask:04o})"
        );

        // Several short reads really happened and none was treated as a
        // failure.
        let events = getrandom_events(&trace);
        assert!(
            events.len() >= 2,
            "short reads should mean multiple getrandom calls: {events:?}"
        );
        assert!(
            events.iter().all(|e| !e.failed() && e.delivered() <= 7),
            "every call was a successful short read: {events:?}"
        );
        let delivered: usize = events.iter().map(GrEvent::delivered).sum();
        assert_eq!(delivered, KEY_LEN, "the draws must add up to 32 bytes");
    }
}

#[test]
fn random_failure_preserves_existing_file_target() {
    let Some(so) = randtrap_so() else {
        eprintln!("skipping: randtrap shim not available on this target");
        return;
    };

    let tmp = Tmp::new("rand-fail-existing-file");
    // The target path is already taken by a regular file.
    let target = Sentinel::file(&tmp.path, "key", b"existing-content", 0o640);
    let parent_mode_before = mode_of(&tmp.path);
    let trace = prepare_trace(&tmp.path, "trace.log");

    let run = run_keygen(
        &tmp.child("key"),
        0o022,
        &so,
        &[("WRAPFILE_TEST_GETRANDOM_FAIL", "1")],
        &trace,
    );
    if !trap_armed(&trace) {
        return;
    }

    assert_eq!(run.rc, 1, "the command must fail");
    assert!(
        run.out.is_empty(),
        "no success message may be printed, got {}",
        String::from_utf8_lossy(&run.out)
    );
    // The random failure must not delete, rewrite, or re-permission the
    // file that was already there.
    target.assert_untouched();
    assert_eq!(
        mode_of(&tmp.path),
        parent_mode_before,
        "parent directory permissions must be untouched"
    );
    assert_no_leftovers(&tmp.path, &["key", "trace.log"]);
}

#[test]
fn random_failure_preserves_symlink_target_and_referent() {
    let Some(so) = randtrap_so() else {
        eprintln!("skipping: randtrap shim not available on this target");
        return;
    };

    let tmp = Tmp::new("rand-fail-symlink");
    let referent = Sentinel::file(&tmp.path, "real", b"real-data", 0o600);
    let link = tmp.child("key");
    std::os::unix::fs::symlink(&referent.path, &link).unwrap();
    let parent_mode_before = mode_of(&tmp.path);
    let trace = prepare_trace(&tmp.path, "trace.log");

    let run = run_keygen(
        &link,
        0o022,
        &so,
        &[("WRAPFILE_TEST_GETRANDOM_FAIL", "1")],
        &trace,
    );
    if !trap_armed(&trace) {
        return;
    }

    assert_eq!(run.rc, 1, "the command must fail");
    assert!(run.out.is_empty(), "no success message may be printed");
    // The link itself is still the same symlink...
    let meta = fs::symlink_metadata(&link).expect("the symlink must still exist");
    assert!(meta.file_type().is_symlink(), "the symlink must not be replaced");
    assert_eq!(
        fs::read_link(&link).unwrap(),
        referent.path,
        "the symlink must still point where it pointed"
    );
    // ...and the object it points to is untouched.
    referent.assert_untouched();
    assert_eq!(
        mode_of(&tmp.path),
        parent_mode_before,
        "parent directory permissions must be untouched"
    );
    assert_no_leftovers(&tmp.path, &["real", "key", "trace.log"]);
}

#[test]
fn shim_without_fault_uses_the_real_random_source() {
    let Some(so) = randtrap_so() else {
        eprintln!("skipping: randtrap shim not available on this target");
        return;
    };

    let tmp = Tmp::new("rand-real");
    let key = tmp.child("key");
    let trace = prepare_trace(&tmp.path, "trace.log");

    // Shim preloaded but no fault configured: the real OS random source is
    // used and the usual success contract holds.
    let run = run_keygen(&key, 0o022, &so, &[], &trace);
    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
    assert!(run.err.is_empty(), "stderr must be empty on success");
    assert_eq!(
        run.out,
        format!("Key saved to {}\n", key.display()).into_bytes(),
        "stdout must be exactly the save-location message"
    );
    let bytes = fs::read(&key).unwrap();
    assert_eq!(bytes.len(), KEY_LEN, "key must be exactly 32 bytes");
    assert_eq!(mode_of(&key), MODE_0600, "key file mode must be exactly 0600");
    assert!(bytes.iter().any(|&b| b != 0), "key must not be all zeroes");
    assert_ne!(
        bytes,
        pattern(KEY_LEN),
        "without a configured fault the shim must not fabricate key bytes"
    );
    assert!(
        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
        "key bytes must never appear on stdout/stderr"
    );
    // The shim never armed, so it trapped nothing.
    assert!(
        getrandom_events(&trace).is_empty(),
        "an unconfigured shim must not intercept the random source"
    );
}

#[test]
fn injection_does_not_affect_version_or_argument_handling() {
    let Some(so) = randtrap_so() else {
        eprintln!("skipping: randtrap shim not available on this target");
        return;
    };

    let tmp = Tmp::new("rand-fail-cli");
    let trace = prepare_trace(&tmp.path, "trace.log");
    let fault = [("WRAPFILE_TEST_GETRANDOM_FAIL", "1")];

    // --version never touches the random source, fault or no fault.
    let run = run_bin(&["--version"], &so, &fault, &trace);
    if !trap_armed(&trace) {
        return;
    }
    assert_eq!(run.rc, 0);
    assert_eq!(run.out, b"wrapfile 0.1.0\n");
    assert!(run.err.is_empty());

    // Argument errors are still rejected with exit code 2 and usage on
    // stderr, before any random draw happens.
    let run = run_bin(&["keygen"], &so, &fault, &trace);
    assert_eq!(run.rc, 2);
    assert!(run.out.is_empty());
    assert!(
        String::from_utf8_lossy(&run.err).contains("Usage:"),
        "usage must be shown for a missing key file path"
    );
    assert_no_leftovers(&tmp.path, &["trace.log"]);
}

toolUseResult.originalFile:
/*
 * randtrap.c -- LD_PRELOAD shim for wrapfile keygen random-source tests.
 *
 * The getrandom crate used by wrapfile issues the getrandom(2) syscall with
 * inline assembly, so symbol interposition (as in the permfail shim) cannot
 * see it. This shim instead installs a seccomp filter (SECCOMP_RET_TRAP)
 * for getrandom inside the guest process and emulates the syscall in a
 * SIGSYS handler, letting the tests make the OS random source fail in
 * controlled ways on a machine where it works fine. The filter only traps
 * getrandom inside the fault-configured guest: every other syscall and
 * every other process -- including other wrapfile invocations -- keeps
 * using the real random source.
 *
 * Activation: only inside an executable whose basename starts with
 * "wrapfile" (checked via /proc/self/exe), and only when one of the fault
 * variables below is set. Everything is configured through the environment:
 *
 *   WRAPFILE_TEST_GETRANDOM_FAIL=1        every getrandom call fails with
 *                                         EIO before a single byte is drawn
 *   WRAPFILE_TEST_GETRANDOM_FAIL_AFTER=N  calls succeed until N bytes in
 *                                         total have been handed out (the
 *                                         first call is truncated to N if
 *                                         needed), then fail with EIO -- a
 *                                         source that dries up mid-key
 *   WRAPFILE_TEST_GETRANDOM_PARTIAL=N     every call returns at most N
 *                                         bytes but always succeeds -- a
 *                                         source that only ever delivers
 *                                         short reads (NOT a failure: the
 *                                         guest must keep drawing)
 *   WRAPFILE_TEST_TRACE_FILE=PATH         one GETRANDOM line per trapped
 *                                         call is appended here, plus a
 *                                         TRAP line when the shim arms
 *
 * Bytes handed to the guest follow a fixed, recognisable pattern that is
 * never valid text (0x80, 0x81, ... by global draw index), so the tests can
 * prove that on success the key file holds exactly the bytes the source
 * delivered -- nothing invented, nothing zero-padded -- and that on failure
 * those bytes leak nowhere: not on stdout/stderr in raw or hex form, and
 * not into any file left behind.
 *
 * The constructor records "TRAP armed" / "TRAP unavailable ..." in the
 * trace file so tests can skip cleanly on kernels without seccomp.
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <sys/prctl.h>
#include <sys/syscall.h>
#include <sys/ucontext.h>
#include <unistd.h>

#include <linux/audit.h>
#include <linux/filter.h>
#include <linux/seccomp.h>

#if defined(__x86_64__)
#define TRAP_AUDIT_ARCH AUDIT_ARCH_X86_64
#elif defined(__aarch64__)
#define TRAP_AUDIT_ARCH AUDIT_ARCH_AARCH64
#else
#error "randtrap supports x86_64 and aarch64 only"
#endif

#ifndef SYS_getrandom
#if defined(__x86_64__)
#define SYS_getrandom 318
#else
#define SYS_getrandom 278
#endif
#endif

enum fault_mode {
    MODE_OFF = 0,
    MODE_FAIL_ALL,   /* every call fails before a single byte is drawn */
    MODE_FAIL_AFTER, /* hand out cfg_arg bytes in total, then fail */
    MODE_PARTIAL     /* every call succeeds but returns at most cfg_arg bytes */
};

static enum fault_mode cfg_mode = MODE_OFF;
static long cfg_arg = 0;
static unsigned long long delivered = 0;
static int trace_fd = -1;

/* The byte handed out at global draw index `index`. The Rust tests
 * recompute the same sequence (see pattern_byte in keygen_random_source.rs). */
static unsigned char pattern_byte(unsigned long long index)
{
    return (unsigned char)(0x80 + (index % 64));
}

/* ----- activation: only inside the wrapfile executable ----- */

static int process_active(void)
{
    char buf[512];
    ssize_t n = readlink("/proc/self/exe", buf, sizeof(buf) - 1);
    if (n <= 0)
        return 0;
    buf[n] = '\0';
    const char *base = strrchr(buf, '/');
    base = base ? base + 1 : buf;
    return strncmp(base, "wrapfile", 8) == 0;
}

/* ----- async-signal-safe trace output ----- */

static size_t str_len(const char *s)
{
    size_t n = 0;
    while (s[n])
        n++;
    return n;
}

static void trace_write(const char *s, size_t n)
{
    if (trace_fd < 0)
        return;
    /* Raw syscall: async-signal-safe and immune to interposition. */
    while (n > 0) {
        long r = syscall(SYS_write, trace_fd, s, n);
        if (r <= 0)
            return;
        s += r;
        n -= (size_t)r;
    }
}

static void trace_str(const char *s)
{
    trace_write(s, str_len(s));
}

static size_t fmt_u64(char *out, unsigned long long v)
{
    char tmp[20];
    size_t n = 0, i;
    do {
        tmp[n++] = (char)('0' + (v % 10));
        v /= 10;
    } while (v);
    for (i = 0; i < n; i++)
        out[i] = tmp[n - 1 - i];
    return n;
}

/* One line per trapped call: "GETRANDOM req=N ret=M" on (possibly short)
 * success, "GETRANDOM req=N ret=-1 errno=EIO" on injected failure. Called
 * from the SIGSYS handler, so it only uses a stack buffer and the raw
 * write syscall. */
static void trace_getrandom(size_t req, long ret)
{
    char line[96];
    size_t n = 0;
    const char *p;

    if (trace_fd < 0)
        return;

    for (p = "GETRANDOM req="; *p; p++)
        line[n++] = *p;
    n += fmt_u64(line + n, (unsigned long long)req);
    for (p = " ret="; *p; p++)
        line[n++] = *p;
    if (ret < 0) {
        for (p = "-1 errno=EIO"; *p; p++)
            line[n++] = *p;
    } else {
        n += fmt_u64(line + n, (unsigned long long)ret);
    }
    line[n++] = '\n';
    trace_write(line, n);
}

/* ----- the emulated getrandom ----- */

static void on_sigsys(int sig, siginfo_t *info, void *uctx)
{
    ucontext_t *uc;
    unsigned char *buf;
    size_t len, k, i;
    long ret;

    (void)sig;
    if (info->si_code != SYS_SECCOMP || info->si_syscall != SYS_getrandom) {
        /* Not our trap: die the way an unhandled SIGSYS would. */
        signal(SIGSYS, SIG_DFL);
        raise(SIGSYS);
        return;
    }

    uc = (ucontext_t *)uctx;
#if defined(__x86_64__)
    buf = (unsigned char *)(uintptr_t)uc->uc_mcontext.gregs[REG_RDI];
    len = (size_t)uc->uc_mcontext.gregs[REG_RSI];
#else
    buf = (unsigned char *)(uintptr_t)uc->uc_mcontext.regs[0];
    len = (size_t)uc->uc_mcontext.regs[1];
#endif

    if (cfg_mode == MODE_FAIL_ALL) {
        ret = -EIO;
    } else if (cfg_mode == MODE_FAIL_AFTER) {
        long long remaining = (long long)cfg_arg - (long long)delivered;
        if (remaining <= 0) {
            ret = -EIO;
        } else {
            k = len < (size_t)remaining ? len : (size_t)remaining;
            for (i = 0; i < k; i++)
                buf[i] = pattern_byte(delivered + i);
            delivered += k;
            ret = (long)k;
        }
    } else { /* MODE_PARTIAL */
        k = len < (size_t)cfg_arg ? len : (size_t)cfg_arg;
        for (i = 0; i < k; i++)
            buf[i] = pattern_byte(delivered + i);
        delivered += k;
        ret = (long)k;
    }

    trace_getrandom(len, ret);

    /* The syscall was never executed; the value left in the return
     * register of the signal frame is what the guest sees. */
#if defined(__x86_64__)
    uc->uc_mcontext.gregs[REG_RAX] = ret;
#else
    uc->uc_mcontext.regs[0] = (unsigned long long)(long long)ret;
#endif
}

/* ----- constructor: arm the trap when a fault is configured ----- */

__attribute__((constructor))
static void randtrap_init(void)
{
    const char *v;
    struct sigaction sa;
    struct sock_filter filter[] = {
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS,
                 (unsigned)offsetof(struct seccomp_data, arch)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, TRAP_AUDIT_ARCH, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
        BPF_STMT(BPF_LD | BPF_W | BPF_ABS,
                 (unsigned)offsetof(struct seccomp_data, nr)),
        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_getrandom, 0, 1),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_TRAP),
        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
    };
    struct sock_fprog prog = {
        .len = (unsigned short)(sizeof(filter) / sizeof(filter[0])),
        .filter = filter,
    };

    if (!process_active())
        return;

    if ((v = getenv("WRAPFILE_TEST_GETRANDOM_FAIL")) && v[0] == '1') {
        cfg_mode = MODE_FAIL_ALL;
    } else if ((v = getenv("WRAPFILE_TEST_GETRANDOM_FAIL_AFTER")) && v[0]) {
        cfg_mode = MODE_FAIL_AFTER;
        cfg_arg = strtol(v, NULL, 10);
    } else if ((v = getenv("WRAPFILE_TEST_GETRANDOM_PARTIAL")) && v[0]) {
        cfg_mode = MODE_PARTIAL;
        cfg_arg = strtol(v, NULL, 10);
        if (cfg_arg < 1)
            cfg_mode = MODE_OFF;
    }
    if (cfg_mode == MODE_OFF)
        return;

    if ((v = getenv("WRAPFILE_TEST_TRACE_FILE")) && v[0])
        trace_fd = open(v, O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0600);

    memset(&sa, 0, sizeof(sa));
    sa.sa_sigaction = on_sigsys;
    sa.sa_flags = SA_SIGINFO;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGSYS, &sa, NULL) != 0) {
        trace_str("TRAP unavailable errno=SIGACTION\n");
        cfg_mode = MODE_OFF;
        return;
    }

    if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0 ||
        prctl(PR_SET_SECCOMP, SECCOMP_MODE_FILTER, &prog) != 0) {
        /* No seccomp on this kernel: leave the real random source alone
         * and let the tests skip themselves. */
        trace_str("TRAP unavailable errno=SECCOMP\n");
        cfg_mode = MODE_OFF;
        return;
    }

    trace_str("TRAP armed\n");
}

