/* One line per trapped call: "GETRANDOM req=N ret=M" on (possibly short)
 * success, "GETRANDOM req=N ret=-1 errno=EIO" on injected failure. Called
 * from the SIGSYS handler, so it only uses a stack buffer and the raw
 * write syscall. */
static void trace_getrandom(size_t req, long ret)
{
    char line[96];
    size_t n = 0;
    const char *p;

    if (trace_fd < 0)
        return;

    for (p = "GETRANDOM req="; *p; p++)
        line[n++] = *p;
    n += fmt_u64(line + n, (unsigned long long)req);
    for (p = " ret="; *p; p++)
        line[n++] = *p;
    if (ret < 0) {
        for (p = "-1 errno=EIO"; *p; p++)
            line[n++] = *p;
    } else {
        n += fmt_u64(line + n, (unsigned long long)ret);
    }
    line[n++] = '\n';
    trace_write(line, n);
}

