#[derive(Debug)]
struct GrEvent {
    req: usize,
    ret: i64, // negative: the call failed with the injected errno
}

impl GrEvent {
    fn failed(&self) -> bool {
        self.ret < 0
    }

    fn delivered(&self) -> usize {
        if self.ret > 0 { self.ret as usize } else { 0 }
    }
}

/// The GETRANDOM lines of the trace, in call order.
fn getrandom_events(trace: &Path) -> Vec<GrEvent> {
    let text = fs::read_to_string(trace).unwrap();
    text.lines()
        .filter_map(|line| {
            let mut parts = line.split_whitespace();
            if parts.next() != Some("GETRANDOM") {
                return None;
            }
            let mut req = None;
            let mut ret = None;
            for kv in parts {
                let (k, v) = kv.split_once('=')?;
                match k {
                    "req" => req = v.parse().ok(),
                    "ret" => ret = v.parse().ok(),
                    _ => {}
                }
            }
            Some(GrEvent { req: req?, ret: ret? })
        })
        .collect()
}

